import React, { useState, useEffect } from 'react';

export default function ItemReview({ userRole }) {
  const [submissions, setSubmissions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const getToken = () => localStorage.getItem('token');

  // --- Fetch pending items for review ---
  const fetchSubmissions = async () => {
    const token = getToken();
    if (!token) return setError("Not authenticated.");

    const ReportItemForm = (
        // Check your original image for the exact form content
        <div className="report-form-container">
            <h2>Report Lost Item</h2>
            {/* ... form inputs and submit button JSX ... */}
        </div>
    );
    
    // 3. Define the admin-specific content
    const AdminReviewContent = (
        <div className="admin-review-list">
            {/* ... Item Review/Claims tables and buttons go here ... */}
        </div>
    );
    try {
      const response = await fetch('/api/admin/submissions', {
        method: 'GET',
        headers: { 'Authorization': `Bearer ${token}` },
      });

      if (response.status === 403) {
         throw new Error("Permission Denied: Requires Moderator or Admin role.");
      }
      if (!response.ok) throw new Error('Failed to fetch submissions.');

      const data = await response.json();
      setSubmissions(data);
    } catch (err) {
      setError(err.message || 'An error occurred.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSubmissions();
  }, []);

  // --- Action Handler: Approve Item ---
  const handleAction = async (itemId, action) => {
    const token = getToken();
    // Use the backend PUT endpoint: /api/admin/submissions/:id/status
    const response = await fetch(`/api/admin/submissions/${itemId}/status`, {
      method: 'PUT',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ status: action }) // 'approved' or 'rejected'
    });

    if (response.ok) {
      alert(`Item ${itemId} ${action}.`);
      fetchSubmissions(); // Refresh the list
    } else {
      alert(`Failed to ${action} item.`);
    }
  };

  if (loading) return <p>Loading review queue...</p>;
  if (error) return <p className="text-red-600 font-semibold">Error: {error}</p>;

  return (
    <div className="p-4">
      <h3 className="text-xl font-semibold mb-4">📝 Item Review & Claim Verification</h3>
      {/* Map through submissions and render a list/table with Approve/Reject/Verify buttons */}
      {submissions.map(item => (
        <div key={item.id} className="border p-3 mb-2 flex justify-between items-center">
          <span>{item.name} - Status: {item.status}</span>
          <div>
            <button onClick={() => handleAction(item.id, 'approved')} className="bg-green-500 text-white p-1 text-sm mr-2">Approve Item</button>
            <button onClick={() => handleAction(item.id, 'rejected')} className="bg-red-500 text-white p-1 text-sm">Reject Item</button>
            {/* You'd have a separate handler for claim verification here, calling /api/admin/claims/:id/verify */}
          </div>
        </div>
      ))}
    </div>
  );
}
